parameters.jsCode:
const imagePrompts = $json.imagePrompts || [];
const baseData = { ...$json };
delete baseData.imagePrompts;

if (imagePrompts.length === 0) {
  return [{ json: { ...baseData, imagesGenerated: 0, savedImages: [] } }];
}

return imagePrompts.map(prompt => ({
  json: {
    ...baseData,
    prompt: prompt.prompt,
    filename: prompt.filename,
    folderName: baseData.folderPath + '/assets',
    currentPrompt: prompt,
    totalPrompts: imagePrompts.length
  }
}));

const fs = require('fs');
const path = require('path');

const assetsPath = path.join($json.folderPath, 'assets');
const filename = $json.currentPrompt.filename;
const imageData = $json.images?.[0] || $json.image || '';

if (!imageData) {
  console.error('No image data received from API');
  return [{ json: { ...$json, imageSaved: false, error: 'No image data' } }];
}

const buffer = Buffer.from(imageData, 'base64');
const imagePath = path.join(assetsPath, filename);

fs.writeFileSync(imagePath, buffer);

return [{ json: {
  ...$json,
  imageSaved: true,
  imagePath,
  imageFilename: filename,
  imageType: $json.currentPrompt.type
} }];

const items = $input.all();

if (items.length === 0) {
  return [{ json: { imagesGenerated: 0, savedImages: [] } }];
}

const baseData = items[0].json;
const savedImages = items.filter(i => i.json.imageSaved).map(i => ({
  filename: i.json.imageFilename,
  type: i.json.imageType,
  path: i.json.imagePath
}));

return [{ json: {
  uniquePostId: baseData.uniquePostId,
  blogId: baseData.blogId,
  title: baseData.title,
  description: baseData.description,
  labels: baseData.labels,
  wordCount: baseData.wordCount,
  readingTime: baseData.readingTime,
  outline: baseData.outline,
  codeExamples: baseData.codeExamples,
  visualElements: baseData.visualElements,
  createdDate: baseData.createdDate,
  folderPath: baseData.folderPath,
  imagesGenerated: savedImages.length,
  savedImages
} }];

const imageList = ($json.savedImages || []).map(img => img.filename).join(', assets/');
const prompt = `You are an expert technical writer. Generate a complete 2,000-2,500 word blog post in HTML format using the data below.

BLOG DATA:
${JSON.stringify($json, null, 2)}

TEMPLATE: Use structure from blogs/computer/template.html

REQUIREMENTS:
- Use all sections from outline with specified word counts
- Include all ${$json.codeExamples?.length || 0} code examples with syntax highlighting classes (highlight-keyword, highlight-string, etc)
- Add comparison tables, info boxes, feature grids from visualElements
- Reference images: assets/${imageList}
- Images generated: ${$json.imagesGenerated || 0}
- Professional writing, second-person (you), active voice
- Complete runnable code examples

Output ONLY the complete HTML content.`;

return [{ json: { ...$json, ollamaPrompt: prompt } }];

